<?php $labels=['new'=>'جديدة','read'=>'مقروءة','replied'=>'تم الرد','archived'=>'مؤرشفة']; ?>
<section class="panel"><div class="panel-head"><div><span class="panel-kicker">التواصل</span><h2>رسائل الزوار</h2></div><span><?=count($rows)?> رسالة</span></div>
<?php if(!$rows):?><div class="empty-state"><strong>لا توجد رسائل بعد.</strong></div><?php else:?><div class="admin-message-list"><?php foreach($rows as $r):?><article class="panel" style="margin:12px 0"><div class="panel-head"><div><span class="status s-<?=e($r['status'])?>"><?=e($labels[$r['status']]??$r['status'])?></span><h3><?=e($r['subject']?:'بدون موضوع')?></h3><small><?=e($r['name'])?> · <a href="mailto:<?=e($r['email'])?>"><?=e($r['email'])?></a> · <?=e($r['locale'])?> · <?=e($r['created_at'])?></small></div></div><p style="white-space:pre-wrap;line-height:1.9"><?=e($r['message'])?></p><form method="post" action="/admin/messages/update" class="form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><label>الحالة<select name="status"><?php foreach($labels as $k=>$v):?><option value="<?=$k?>" <?=$r['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label class="span-2">ملاحظة الإدارة<textarea name="admin_note" rows="3"><?=e($r['admin_note']??'')?></textarea></label><button class="btn btn-primary">حفظ</button></form><form method="post" action="/admin/messages/delete" onsubmit="return confirm('حذف الرسالة؟')" style="margin-top:8px"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-danger">حذف</button></form></article><?php endforeach;?></div><?php endif;?></section>
